// Генератор тестовых CV (PDF, без зависимостей) для #344b9a — парсинг CV заполняет «ציפיות שכר».
// Запуск: node fixtures/make-cv-pdf.mjs   (из .qa/e2e) — пересоздаёт PDF рядом с этим файлом.
// Люди вымышленные, префикс QA-AUTO. Латиница: стандартный шрифт PDF Helvetica не содержит иврит.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));

const esc = (s) => s.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');

function makePdf(lines) {
  const text = lines
    .map((l, i) => `BT /F1 ${i === 0 ? 16 : 12} Tf 72 ${740 - i * 22} Td (${esc(l)}) Tj ET`)
    .join('\n');
  const objs = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>',
    `<< /Length ${Buffer.byteLength(text, 'latin1')} >>\nstream\n${text}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  ];
  let out = '%PDF-1.4\n';
  const offsets = [];
  objs.forEach((o, i) => {
    offsets.push(Buffer.byteLength(out, 'latin1'));
    out += `${i + 1} 0 obj\n${o}\nendobj\n`;
  });
  const xref = Buffer.byteLength(out, 'latin1');
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((n) => `${String(n).padStart(10, '0')} 00000 n \n`).join('');
  out += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, 'latin1');
}

const common = [
  'Email: qa-auto-cv@example.com   Phone: 050-000-0099',
  'Summary: QA automation engineer, 5 years of experience (test CV, not a real person).',
  'Experience: 2021-2026 QA Automation Engineer, QA-AUTO Labs Ltd. Playwright, TypeScript.',
  'Education: B.Sc. Computer Science, QA-AUTO University, 2017-2020.',
  'Languages: Hebrew, English.',
];

const files = {
  // #344b9a: «Expected salary: 22,000 - 26,000 NIS per month» → מ- 22000 / עד 26000 (מה רצוי, Done when)
  'qa-auto-cv-salary-range.pdf': ['QA-AUTO Salary Testcv', ...common, 'Expected salary: 22,000 - 26,000 NIS per month'],
  // контроль: зарплаты в CV нет → поля зарплаты пустые («nothing is invented»)
  'qa-auto-cv-no-salary.pdf': ['QA-AUTO Nosalary Testcv', ...common],
};

for (const [name, lines] of Object.entries(files)) {
  writeFileSync(join(here, name), makePdf(lines));
  console.log('written', join(here, name));
}
